// The LOGS workspace, AS GRAPH SOURCE (#3646, epic #3604). Transcribed from the live feature file: the
// runtime loader compiles this and mounts it, resolving every import to the app's real modules (the
// shared/ui design system + the store via appModules, the audit derivation via the logs graph-platform,
// and the sibling tab bodies as sibling records). Behaviour runs here — no forked render path.
//
// ONE SCREEN FOR EVERY HISTORY THE APP KEEPS (epic-a-unified-logs-workspace). The `bsc logs` engine
// (#1607) already carries eight streams — audit · skill · mcp · hook · coord · activity · done · perm —
// plus the `sessions` / `waiting` / `cost` rollups, and almost none of it was reachable from the UI. This
// is a SURFACE over something already built, which is why it starts with one real tab rather than seven
// stubs: Sessions, Waiting, Skills, Hooks, Cost and Streams each land as their own slice.
//
// WHERE THIS SCREEN CAME FROM. It was the Security workspace, which held four tabs. Three were deleted
// (retire-agentprofile-and-strip-security-to-activity) and are not coming back:
//
//   Profiles     — it edited an `AgentProfile` while CALLING it a "role" ("New role", "Delete role"),
//                  which is the duplication the persona floor replaced. Capability is authored with
//                  `bsc persona`, by the architect, and READ on the Teams panel. No CRUD in the UI.
//   Assignments  — it mapped a pane to a profile. With no profile authoring surface there is nothing
//                  to assign; launch resolves a pane's capability from its persona floor.
//   Flow         — it rendered "which sessions are parked on a dependency (#199)". That mechanism was
//                  REMOVED in #1039: the emitter it advertised no longer exists, there is no coordinator
//                  auto-wake, and `dependsOn` is a planning-time hint. So the view could only ever be
//                  empty, and #4174 already caught its empty state naming that removed command — which
//                  is why THIS comment does not spell it either: `logsRecordContent.test.ts` sweeps every
//                  packaged record for the literal, because a record IS the screen. The live question
//                  Flow reached for — WHO IS STUCK — is answered by `bsc logs waiting`, fed by
//                  `bsc-wait`, and becomes the Waiting tab here. Do not rebuild Flow.
//
// Activity is the one that survived, because it has a real feed behind it — and it is history, which is
// what this workspace is for.
//
// The `AgentProfile` MODEL is deliberately still wired: `buildSecurityPayload` ships it to
// mobile-studio-code over the tunnel against a byte-exact fixture, and CLAUDE.md requires coordinated
// PRs in both repos for a protocol break. Retiring it is `retire-the-agentprofile-model-behind-the-tunnel-contract`.
// The audit feed still resolves each row's decision from profile ∪ role, so those store reads stay.
import { useMemo, useState } from "react";
import { usePoll } from "@/shared/hooks/usePoll";
import { logsTail } from "@/shared/lib/core/logsBridge";
import { type TabItem } from "@/shared/ui/layouts/TabBar";
import { Screen } from "@/shared/ui/layouts/Screen";
import { usePageTabs } from "@/shared/hooks/usePageTabs";
import { APP_ROLES } from "@/shared/lib/security/agentProfiles";
import { deriveConsoles } from "@/shared/lib/security/consoleModel";
import {
  buildAuditRows, auditDecisionCounts, type AuditDisplayRow, type DecFilter,
} from "@/features/logs/lib/auditRows";
import { useAppStore } from "@/store";
import { ActivityTab } from "@/features/logs/ActivityTab";

export function LogsWorkspace({ pageOverride }: { pageOverride?: string } = {}) {
  const [actDecision, setActDecision] = useState<DecFilter>("all");
  const [actConsole, setActConsole] = useState("all");

  // Read-only: these feed the audit derivation and the row's profile chip, nothing edits them here.
  const profiles = useAppStore((s) => s.agentProfiles);
  const tabs = useAppStore((s) => s.tabs);
  const paneNames = useAppStore((s) => s.paneNames);
  const disabledPanes = useAppStore((s) => s.disabledPanes);
  const paneProfiles = useAppStore((s) => s.paneProfiles);
  const activeRepoName = useAppStore((s) => s.activeRepoName);

  // Live console/pane model derived from the real workspace tabs (see shared/lib/security/consoleModel).
  const consoles = useMemo(
    () => deriveConsoles({ tabs, paneNames, disabledPanes, paneProfiles, activeRepoName }),
    [tabs, paneNames, disabledPanes, paneProfiles, activeRepoName],
  );

  // Activity audit (#257): load the real per-pane tool log and derive each decision
  // from the pane's resolved gate (profile ∪ role) — the same rules the launch gate
  // applies. Refreshed while the Activity tab is open.
  const paneRoles = useAppStore((s) => s.paneRoles);
  const [auditRows, setAuditRows] = useState<AuditDisplayRow[]>([]);

  const logDefs: TabItem[] = useMemo(() => [
    { id: "activity", label: "Activity", count: auditRows.length, hint: "· tool attempts" },
  ], [auditRows.length]);
  const { tabs: logTabs, activeId, select, reorder, tearOff } = usePageTabs("logs", logDefs);
  const tab = pageOverride ?? activeId; // active section

  usePoll(async (isCancelled) => {
    if (tab !== "activity") return;
    const lines = await logsTail("audit", 300);
    const rows = buildAuditRows(lines, { consoles, profiles, paneProfiles, paneRoles });
    if (!isCancelled()) setAuditRows(rows);
  }, 3000, [tab, paneProfiles, profiles, paneRoles, consoles]);

  // The row chip's colour lookup — application roles are singletons, user profiles are stored.
  const find = (id: string) => [...APP_ROLES, ...profiles].find((p) => p.id === id);

  const { allow, ask, block } = auditDecisionCounts(auditRows);

  return (
    <Screen
      tabs={logTabs}
      active={tab}
      onSelect={select}
      onReorder={reorder}
      onTearOff={tearOff}
      pageOverride={pageOverride}
      className="logs-page"
      bodyClassName="body"
    >
      {tab === "activity" && (
        <ActivityTab
          rows={auditRows} consoles={consoles}
          actDecision={actDecision} setActDecision={setActDecision}
          actConsole={actConsole} setActConsole={setActConsole}
          allow={allow} ask={ask} block={block} find={find}
        />
      )}
    </Screen>
  );
}
